def free_time_slots(intervals, day_start, day_end):
    gaps = []
    cursor = day_start
    for start, end in intervals:
        if start > cursor:
            gaps.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < day_end:
        gaps.append((cursor, day_end))
    return gaps

