def center_text_block(lines, width):
    output = []
    for line in lines:
        pad = width - len(line)
        if pad <= 0:
            output.append(line)
        else:
            left_pad = pad // 2
            right_pad = pad - left_pad
            output.append(' ' * left_pad + line + ' ' * right_pad)
    return output

