def week_start_date(year, month, day):
    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def prev_day(y, m, d):
        d -= 1
        if d >= 1:
            return (y, m, d)
        m -= 1
        if m < 1:
            m, y = 12, y - 1
        lengths = month_lengths[:]
        if is_leap(y):
            lengths[1] = 29
        return (y, m, lengths[m - 1])
    t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
    y, m = (year - 1, month) if month < 3 else (year, month)
    dow = ((y + y // 4 - y // 100 + y // 400 + t[month - 1] + day) % 7 + 6) % 7
    cy, cm, cd = year, month, day
    for _ in range(dow):
        cy, cm, cd = prev_day(cy, cm, cd)
    return (cy, cm, cd)

def rank_normalize_scores(scores):
    n = len(scores)
    if n <= 1:
        return [0.0] * n
    ordered = sorted(scores)
    first_index = {}
    for idx, val in enumerate(ordered):
        if val not in first_index:
            first_index[val] = idx
    return [round(first_index[val] / (n - 1), 4) for val in scores]

